package com.jonaslins.curso;
import java.nio.charset.StandardCharsets; import java.security.Key; import java.util.*; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import io.jsonwebtoken.*;
@Service class JwtService { private final Key key; JwtService(@Value("${app.jwt-secret}")String secret){key=new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256");} String create(AppUser u){var now=new Date();return Jwts.builder().subject(u.email).claim("role",u.role).issuedAt(now).expiration(new Date(now.getTime()+1000L*60*60*8)).signWith(key).compact();} String email(String token){return Jwts.parser().verifyWith((javax.crypto.SecretKey)key).build().parseSignedClaims(token).getPayload().getSubject();} }
